changeSet.sql:
CREATE TABLE organization_gateways ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
organization_id uuid NOT NULL, gateway_name varchar(32) NOT NULL CHECK (gateway_name IN ('PAYSTACK', 'FLUTTERWAVE', 'MONNIFY', 'OPAY', 'TITAN')), status varchar(32) NOT NULL CHECK (status IN ('CONNECTED', 'PENDING')), connected_at timestamp(6) with time zone,
PRIMARY KEY (id) );
COMMENT ON TABLE organization_gateways IS 'TODO: no credentials live here, and none should ever be added. API keys and secrets belong in a secrets manager, never in the application database — "just one encrypted column" is exactly how credentials end up in a database backup. This table only ever records connection status. Stripe is not a Nigerian local rail — local collection runs through gateway_name''s enumerated providers; diaspora payments use virtual accounts or international wire. Do not add Stripe to that CHECK constraint.';
